  if(/halberd|hellebarde|pike|lanze|glaive|gleve|spear/.test(text))return 'spear';
  if(/flail|flegel/.test(text))return 'flail';
  if(/axe|axt|beil|cleaver|sichel/.test(text))return 'axe';
  if(/hammer|maul|mace|keule|crypt_maul|kryptenbrecher/.test(text))return 'hammer';
  if(/scepter|sceptre|zepter|focus|fokus/.test(text))return 'scepter';
  if(/staff|wand|stab|branch|ast|crozier|totem|orakel|soul|seelen/.test(text))return 'staff';
