    b.poly([[10,13+bob],[12,10+bob],[15,9+bob],[19,9+bob],[22,12+bob],[22,14+bob],[11,14+bob]],c.main);b.line(12,10+bob,19,10+bob,c.light);b.rect(headX-1,9+bob,2,5,c.trim);
    if(back){b.rect(10,14+bob,13,7,c.dark);b.line(12,15+bob,12,19+bob,c.light);}else {b.rect(side?20:11,15+bob,side?3:11,1,P.ink);if(!side){b.rect(10,16+bob,2,4,c.main);b.rect(21,16+bob,2,4,c.dark);}else b.rect(12,15+bob,3,5,c.main);}
