  if(look.slots.weapon){for(const [start,length,color] of BASE_WEAPON_PATCHES[BASE_WEAPON_PATCH_INDEX[CLASSES.indexOf(look.classId)][direction*8+pose]])for(let index=start;index<start+length;index++){b.eraseMask[index]=1;b.pixels[index]=color;}}
